sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float strength;
uniform float radius;
uniform float detail;
half4 main(float2 coord)
{
    half4 c = image.eval(coord);
    if (c.a <= 0.001) return half4(0.0);
    half3 col = c.rgb / c.a;
    float s = max(radius, 0.5);
    float rs = mix(0.35, 0.03, clamp(detail, 0.0, 1.0));
    float inv2s2 = 1.0 / (2.0 * s * s);
    float inv2r2 = 1.0 / (2.0 * rs * rs);
    half3 sum = half3(0.0);
    float wsum = 0.0;
    for (int y = -2; y <= 2; y++)
    {
        for (int x = -2; x <= 2; x++)
        {
            float2 off = float2(float(x), float(y)) * s;
            half4 sc = image.eval(coord + off);
            if (sc.a <= 0.001) continue;
            half3 sc3 = sc.rgb / sc.a;
            float d2 = float(dot(off, off));
            float ws = exp(-d2 * inv2s2);
            half3 diff = sc3 - col;
            float cd2 = float(dot(diff, diff));
            float wr = exp(-cd2 * inv2r2);
            float w = ws * wr;
            sum += sc3 * half(w);
            wsum += w;
        }
    }
    half3 filtered = col;
    if (wsum > 0.00001)
    {
        filtered = sum / half(wsum);
    }
    half3 outc = clamp(mix(col, filtered, half(clamp(strength, 0.0, 1.0))), 0.0, 1.0);
    return half4(outc * c.a, c.a);
}
